class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport) -> dict:
    """Invoke a configured endpoint, retrying transient failures immediately."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    retry = endpoint_cfg["retry"]
    max_attempts = retry + 1

    attempts = 0

    while attempts < max_attempts:
        attempts += 1
        try:
            result = transport(url, timeout_ms)
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts >= max_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }

    # A valid configuration has retry >= 0, so this path is unreachable.
    raise ValueError("retry must be non-negative")
